module "network" {
  source = "./modules/network"
}
# Child module declares output "subnet_id"

variable "replicas" {
  type = number
  validation {
    condition     = var.replicas > 0
    error_message = "replicas must be positive."
  }
}

resource "terraform_data" "pool" {
  for_each = { dev = 1, prod = 3 }
  input    = each.value
}

resource "aws_instance" "app" {
  ami           = var.ami_id
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.app.id
}

terraform {
  backend "s3" {
    bucket = var.state_bucket
    key    = "app.tfstate"
    region = "us-east-1"
  }
}
